(function () {
  'use strict';
  const S = window.Studio, R = S.Runtime, E = S.escape;
  const ui = { query: '', status: 'all', kind: 'all', page: 1, eventCount: 60, expanded: '' };
  const labels = {
    running: ['运行中', 'info'], waiting: ['等待处理', 'warning'], done: ['已完成', 'success'], failed: ['失败', 'danger'],
    rejected: ['已拒绝', 'danger'], stopped: ['已停止', 'neutral'], skipped: ['未执行', 'neutral'], queued: ['等待前置', 'neutral'],
    success: ['成功', 'success'], cancelled: ['已取消', 'neutral'], pending: ['待处理', 'warning'], error: ['失败', 'danger']
  };
  const kinds = { 'plan-execution':'多 Agent 协作', workflow:'工作流', subworkflow:'子工作流', 'tool-debug':'工具调试', 'node-debug':'节点调试', agent:'Agent 对话', 'workflow-debug':'工作流调试' };
  const status = value => S.badge(...(labels[value] || [value || '待执行', 'neutral']));
  const json = (value, label = '数据') => `<pre class="run-json" tabindex="0" aria-label="${E(label)}">${E(value === undefined ? '未产生' : JSON.stringify(value, null, 2))}</pre>`;
  const date = value => value ? new Intl.DateTimeFormat('zh-CN', { timeZone:'Asia/Shanghai', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false }).format(new Date(value)) : '—';
  const duration = value => value == null ? '—' : value < 1000 ? Math.max(0, Math.round(value)) + ' ms' : (value / 1000).toFixed(2) + ' s';
  const durationOf = item => item.duration ?? (item.endedAt && item.startedAt ? item.endedAt - item.startedAt : undefined);
  const current = () => R.findRun(S.params.id) || S.state.runs[0];
  const outcome = run => run.outcome || { artifacts:run.artifacts || [], receipts:[] };
  const actions = (run, small = false) => run.status === 'running' || run.status === 'waiting' ? S.btn('停止运行', 'run-stop', {variant:'secondary',icon:'stop',small,attrs:`data-id="${E(run.id)}"`}) : run.kind==='plan-execution'?`<a class="btn btn-secondary" href="#plan?id=${encodeURIComponent(run.planSourceRunId)}">查看或复制计划</a>`: run.engine ? S.btn('重新运行', 'run-rerun', {variant:'secondary',icon:'refresh',small,attrs:`data-id="${E(run.id)}"`}) : '';
  const resultLabel = run => {
    const o = outcome(run), list = [];
    if (Object.hasOwn(o, 'returnValue')) list.push('有返回值');
    if (o.receipts?.length) list.push(o.receipts.length + ' 条回执');
    if ((o.artifacts || []).length) list.push(o.artifacts.length + ' 个文件');
    return list.join(' · ') || (run.status === 'done' ? '无返回值' : '—');
  };
  function toolCard(run, call, compact = false) {
    const tool = R.getTool(call.toolId), conn = R.getConnection(call.connectionId);
    return `<details class="run-tool-card ${compact ? 'is-compact' : ''}" ${!compact && call.status === 'failed' ? 'open' : ''}><summary><span class="run-type-icon">${S.icon(tool?.kind === 'plugin' ? 'box' : 'plug',16)}</span><span class="run-tool-name"><strong>${E(call.toolName || tool?.title || call.toolId)}</strong><small>${E(conn?.name || call.connectionId || '工具')} · ${E(call.version || tool?.version || '—')}</small></span>${status(call.status)}<span class="mono small muted">${duration(durationOf(call))}</span></summary><div class="run-tool-body"><div class="run-id-line"><span>Tool call</span><code>${E(call.id)}</code><a href="#task?id=${encodeURIComponent(run.id)}&tab=trace&call=${encodeURIComponent(call.id)}" class="text-link">查看调用链 ${S.icon('arrow',12)}</a></div><div class="grid-2"><section><h4>已解析实参</h4>${json(call.args,'工具调用实参')}</section><section><h4>${call.error ? '错误' : '结构化结果'}</h4>${json(call.error || call.result, '工具结果')}</section></div>${call.error ? '<p class="run-error-line">本次调用未成功；保留输入与错误，可在运行详情新建调试。</p>' : ''}</div></details>`;
  }
  function approval(run, context = 'task') {
    const p = run.pending;
    if (!p || run.status !== 'waiting') return '';
    if (p.kind === 'breakpoint') return `<section class="run-approval"><div class="row"><span class="run-pending-icon">${S.icon('pause',20)}</span><div><h3>已停在断点</h3><p class="small muted">${E(p.title || p.nodeId || '下一节点执行前')}</p></div></div><div class="run-approval-actions">${S.btn('继续执行', 'run-resume', {icon:'play',attrs:`data-id="${E(run.id)}"`})}</div></section>`;
    const fields = Array.isArray(p.fields) ? p.fields : [];
    return `<section class="run-approval" aria-label="待处理的运行确认"><div class="row"><span class="run-pending-icon">${S.icon('shield',20)}</span><div><h3>${E(p.title || '需要你确认')}</h3><p class="small muted">${E(p.description || '核对本次操作与参数，确认后从等待位置继续。')}</p></div></div>${p.preview ? `<div class="run-preview-text">${E(typeof p.preview === 'string' ? p.preview : JSON.stringify(p.preview,null,2))}</div>` : ''}${p.args ? `<details><summary>查看待执行参数</summary>${json(p.args)}</details>` : ''}<form id="run-approval-${E(run.id)}-${E(context)}" data-form="run-approval" data-id="${E(run.id)}" data-pending="${E(p.id)}" novalidate>${fields.map((f,i) => { const name = f.name || f.key || 'field' + i, id = 'run-input-' + run.id + '-' + context + '-' + i; return f.type === 'boolean' ? `<label class="run-check"><input type="checkbox" name="${E(name)}" ${f.default ? 'checked' : ''}> ${E(f.label || name)}</label>` : `<div class="field"><label class="field-label" for="${E(id)}">${E(f.label || name)}${f.required ? '<span class="required-star">*</span>' : ''}</label>${['number','integer'].includes(f.type) ? `<input class="input" id="${E(id)}" name="${E(name)}" type="number" value="${E(f.default ?? f.value ?? '')}">` : `<textarea class="textarea" id="${E(id)}" name="${E(name)}" style="resize:none" rows="3">${E(typeof(f.default ?? f.value)==='object'?JSON.stringify(f.default ?? f.value,null,2):(f.default ?? f.value ?? ''))}</textarea>`}<p class="field-error" id="${E(id)}-error"></p></div>`; }).join('')}<p class="field-error" data-approval-error role="alert">${E((p.validationErrors||[]).join("；"))}</p></form><div class="run-approval-actions"><span class="small muted">确认仅适用于当前步骤与参数</span>${S.btn('拒绝', 'run-approve', {variant:'secondary',attrs:`data-id="${E(run.id)}" data-approved="false" data-pending="${E(p.id)}" data-context="${E(context)}"`})}${S.btn(p.kind === 'input' ? '提交并继续' : '批准并继续', 'run-approve', {icon:'check',attrs:`data-id="${E(run.id)}" data-approved="true" data-pending="${E(p.id)}" data-context="${E(context)}"`})}</div></section>`;
  }
  function artifacts(run) {
    const list = outcome(run).artifacts || run.artifacts || [];
    return list.length ? `<section class="panel panel-pad"><div class="section-heading"><h3 class="section-title">文件</h3><span class="small muted">${list.length} 个显式生成的文件</span></div><div class="run-file-list">${list.map((a,i)=>`<div class="run-file"><span class="run-type-icon">${S.icon('file',20)}</span><div><strong>${E(a.name || a.filename)}</strong><p class="small muted">${E(a.type || a.format || '文件')}</p></div>${S.btn('预览', 'run-file-preview', {variant:'ghost',small:true,attrs:`data-id="${E(run.id)}" data-index="${i}"`})}${S.btn('下载', 'run-file-download', {variant:'secondary',small:true,icon:'download',attrs:`data-id="${E(run.id)}" data-index="${i}"`})}</div>`).join('')}</div></section>` : '';
  }
  function results(run) {
    const o = outcome(run), returned = Object.hasOwn(o,'returnValue'), receipts = o.receipts || [];
    return `<div class="run-results">${run.status === 'done' ? `<section class="run-complete"><span class="run-complete-mark">${S.icon('check',24)}</span><div><h2>运行已完成</h2><p>${E(o.message || (receipts.length ? '已完成配置的操作，以下是目标位置与回执。' : returned ? '流程已返回配置的数据。' : '流程成功结束，没有配置返回值或文件。'))}</p></div>${S.badge('执行成功','success')}</section>` : run.status === 'failed' ? `<section class="notice warning run-error-panel"><h3>运行未完成</h3><p>${E(run.error?.message || run.error || '查看调用链中的失败节点。')}</p><p class="small">已成功的步骤仍保留；重跑会新建运行记录。</p></section>` : ''}${receipts.length ? `<section class="panel panel-pad"><div class="section-heading"><h3 class="section-title">目标位置与操作回执</h3>${S.badge('模拟写入','info')}</div><div class="run-receipts">${receipts.map((r,i)=>`<div class="run-receipt"><span class="run-type-icon">${S.icon('folder',20)}</span><div><strong>${E(r.title || '目标已更新')}</strong><code>${E(r.destination || r.uri || '已配置目标')}</code><small>${E(r.id)} · ${date(r.at)}</small></div>${S.btn('查看回执','run-receipt',{variant:'secondary',small:true,attrs:`data-id="${E(run.id)}" data-index="${i}"`})}</div>`).join('')}</div><p class="field-help">这些回执来自本地模拟适配器，没有向外部系统写入内容。</p></section>` : ''}${returned ? `<section class="panel panel-pad"><div class="section-heading"><h3 class="section-title">流程返回值</h3>${S.btn('复制','run-copy-result',{variant:'ghost',small:true,icon:'copy',attrs:`data-id="${E(run.id)}"`})}</div>${json(o.returnValue,'流程返回值')}</section>` : run.status === 'done' ? `<div class="run-empty-return"><span>${S.icon('layers',18)}</span><div><strong>没有流程返回值</strong><p>内部节点输出保留在调用链中。任务完成不需要额外生成文件。</p></div><a href="#task?id=${encodeURIComponent(run.id)}&tab=trace" class="text-link">查看执行记录 ${S.icon('arrow',12)}</a></div>` : ''}${artifacts(run)}</div>`;
  }
  S.RunUI = { status, json, toolCard, approval, results, duration, resultLabel };
  S.page('tasks', {title:'运行记录',section:'运行与改进',render(){
    const all = S.state.runs, filtered = all.filter(r=>(ui.status==='all'||r.status===ui.status)&&(ui.kind==='all'||r.kind===ui.kind)&&(r.title+' '+r.id+' '+r.source+' '+r.agent).toLowerCase().includes(ui.query.toLowerCase()));
    const pages = Math.max(1,Math.ceil(filtered.length/9)); ui.page = Math.min(ui.page,pages);
    return `<div class="run-page">${S.header('RUNS / ACTIVITY','让每一步，都有记录。','从工作流、Agent 到单次工具调试，查看执行状态、操作结果与调用链。',`<a href="#workflows" class="btn btn-primary">${S.icon('play',15)}运行工作流</a>`)}<div class="run-list-summary"><span><i class="tiny-dot"></i>${all.filter(r=>r.status==='running').length} 项运行中</span><span>${S.icon('shield',14)} ${all.filter(r=>r.status==='waiting').length} 项等待处理</span><span>${all.filter(r=>r.status==='done').length} 项已完成</span><span class="muted">完成状态与文件产物独立记录</span></div><div class="toolbar run-filters">${S.search('run-query','搜索运行名称或编号',ui.query)}<select class="select" id="run-status" aria-label="筛选运行状态">${[['all','全部状态'],['running','运行中'],['waiting','等待处理'],['done','已完成'],['failed','失败'],['stopped','已停止']].map(([v,l])=>`<option value="${v}" ${ui.status===v?'selected':''}>${l}</option>`).join('')}</select><select class="select" id="run-kind" aria-label="筛选运行来源"><option value="all">全部来源</option>${Object.entries(kinds).map(([v,l])=>`<option value="${v}" ${ui.kind===v?'selected':''}>${l}</option>`).join('')}</select>${S.btn('比较运行','run-compare',{variant:'secondary',icon:'layers',attrs:all.length<2?'disabled':''})}</div><section class="panel"><div class="table-wrap"><table class="data-table run-table"><thead><tr><th>运行 / 版本</th><th>来源</th><th>状态</th><th>结果</th><th>开始时间</th><th><span class="run-sr-only">操作</span></th></tr></thead><tbody>${filtered.slice((ui.page-1)*9,ui.page*9).map(r=>`<tr><td><a class="run-row-title" href="#task?id=${encodeURIComponent(r.id)}">${E(r.title)}</a><div class="small mono muted">${E(r.id)} · ${E(r.version || '草稿')}</div></td><td>${E(kinds[r.kind] || r.source || '演示任务')}${r.parentRunId?'<span class="run-child-label">嵌套运行</span>':''}</td><td>${status(r.status)}</td><td class="small">${E(resultLabel(r))}</td><td class="small mono muted">${date(r.created)}</td><td><a class="icon-btn" href="#task?id=${encodeURIComponent(r.id)}" aria-label="查看${E(r.title)}">${S.icon('arrow',16)}</a></td></tr>`).join('')}</tbody></table></div>${!filtered.length?S.empty('没有匹配的运行','调整筛选条件，或开始一次工具调试。',S.btn('清除筛选','run-clear-filters',{variant:'secondary'})):''}<div class="run-pagination"><span class="small muted">共 ${filtered.length} 条 · 第 ${ui.page} / ${pages} 页</span><div class="row">${S.btn('上一页','run-page',{variant:'secondary',small:true,attrs:`data-page="${ui.page-1}" ${ui.page===1?'disabled':''}`})}${S.btn('下一页','run-page',{variant:'secondary',small:true,attrs:`data-page="${ui.page+1}" ${ui.page===pages?'disabled':''}`})}</div></div></section></div>`;
  },mount(root){
    let timer;
    root.querySelector('#run-query').addEventListener('input',ev=>{if(ev.isComposing)return;clearTimeout(timer);const input=ev.target;ui.query=input.value;timer=setTimeout(()=>{ui.page=1;S.render();const n=document.getElementById('run-query');n?.focus();},250);});
    root.querySelector('#run-query').addEventListener('compositionend',ev=>{ui.query=ev.target.value;ui.page=1;S.render();});
    root.querySelector('#run-status').addEventListener('change',ev=>{ui.status=ev.target.value;ui.page=1;S.render();});
    root.querySelector('#run-kind').addEventListener('change',ev=>{ui.kind=ev.target.value;ui.page=1;S.render();});
    return ()=>clearTimeout(timer);
  }});
  S.action('run-clear-filters',()=>{Object.assign(ui,{query:'',kind:'all',status:'all',page:1});S.render();});
  S.action('run-page',el=>{ui.page=+el.dataset.page;S.render();});
  function executionGraph(run) {
    const graph = run.workflowSnapshot || run.snapshot;
    if (!graph?.nodes?.length) return '';
    const cols=4, size=200, row=105, width=Math.min(cols,graph.nodes.length)*size, height=Math.ceil(graph.nodes.length/cols)*row+24;
    const byId=new Map(graph.nodes.map((n,i)=>[n.id,{n,x:(i%cols)*size+12,y:Math.floor(i/cols)*row+12}]));
    return `<div class="run-graph-scroll"><svg class="run-graph" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="本次运行的图与节点状态">${(graph.edges||[]).map(edge=>{const a=byId.get(edge.source),b=byId.get(edge.target);if(!a||!b)return '';return `<path d="M${a.x+85},${a.y+64} C${a.x+85},${a.y+92} ${b.x+85},${b.y-18} ${b.x+85},${b.y}"/><text x="${(a.x+b.x)/2+90}" y="${(a.y+b.y)/2+44}" class="run-edge-label">${E(edge.sourcePort==='next'?'':edge.sourcePort)}</text>`;}).join('')}${[...byId.values()].map(({n,x,y})=>{const executions=(run.nodeExecutions||[]).filter(z=>z.nodeId===n.id), ex=executions[executions.length-1], state=ex?.status||'queued';return `<g class="run-graph-node is-${E(state)}" transform="translate(${x},${y})"><rect width="174" height="65" rx="9"/><text x="13" y="23" class="run-node-title">${E(n.title.length>12?n.title.slice(0,12)+'…':n.title)}</text><text x="13" y="46">${E(labels[state]?.[0]||state)} · ${E(R.nodeType(n.type)?.name||n.type)}</text></g>`;}).join('')}</svg></div>`;
  }
  function trace(run) {
    if (!run.engine) return `<section class="panel panel-pad">${S.empty('这条历史示例没有逐节点事件','新启动的工作流、Agent 和工具调试会记录统一调用链。')}<a class="btn btn-secondary" href="#mcp">打开 MCP 调试</a></section>`;
    const executions=run.nodeExecutions||[], calls=run.toolCalls||[], children=S.state.runs.filter(x=>x.parentRunId===run.id);
    const selectedCall=calls.find(x=>x.id===S.params.call), selected=executions.find(x=>x.id===S.params.execution)||executions.find(x=>x.status==='failed')||executions[executions.length-1];
    const total=Math.max(1,(run.finishedAt||Date.now())-run.created), left=start=>Math.max(0,Math.min(98,((start||run.created)-run.created)/total*100)), wid=item=>Math.max(1,Math.min(100-left(item.startedAt),((item.endedAt||Date.now())-(item.startedAt||run.created))/total*100));
    return `<section class="panel run-trace-panel"><div class="run-panel-head"><div><h3>执行图</h3><p class="small muted">未选中的分支保留为“未执行”，没有伪造的输出。</p></div><span class="small mono muted">${executions.length} 次节点执行 · ${calls.length} 次工具调用</span></div>${executionGraph(run) || '<p class="run-inset small muted">此运行由工具调用或 Agent 发起，见下方调用树。</p>'}</section><div class="run-trace-grid"><section class="panel"><div class="run-panel-head"><h3>调用树与耗时</h3><span class="small muted">含等待时间</span></div><div class="run-waterfall-axis"><span>0 ms</span><span>${duration(total)}</span></div><div class="run-span-list">${executions.map(ex=>`<button type="button" class="run-span ${selected?.id===ex.id&&!selectedCall?'is-selected':''} ${ex.parentExecutionId?'is-child':''}" data-action="run-select-execution" data-id="${E(ex.id)}"><span class="run-span-name">${S.icon(R.nodeType(ex.type)?.icon||'workflow',14)}<strong>${E(ex.title)}</strong>${ex.itemIndex!=null?`<small>#${ex.itemIndex}</small>`:''}${ex.round!=null?`<small>第 ${ex.round} 轮</small>`:''}</span>${status(ex.status)}<span class="run-span-track"><i class="is-${E(ex.status)}" style="left:${left(ex.startedAt)}%;width:${wid(ex)}%"></i></span><span class="mono small">${duration(durationOf(ex))}</span></button>${calls.filter(c=>c.nodeExecutionId===ex.id).map(c=>spanCall(c,run,total)).join('')}`).join('')}${calls.filter(c=>!c.nodeExecutionId||!executions.some(x=>x.id===c.nodeExecutionId)).map(c=>spanCall(c,run,total)).join('')}${!executions.length&&!calls.length?'<p class="run-inset muted small">还没有节点或工具调用；查看事件记录了解当前状态。</p>':''}</div>${children.map(c=>`<a class="run-child-link" href="#task?id=${encodeURIComponent(c.id)}">${S.icon('workflow',16)}<span>${E(c.title)}<small>${E(c.id)}</small></span>${status(c.status)}${S.icon('arrow',15)}</a>`).join('')}</section><section class="panel run-inspector"><div class="run-panel-head"><h3>${selectedCall?'工具调用详情':selected?'节点执行详情':'选择一项执行'}</h3></div>${selectedCall?`<div class="run-inspector-body"><div class="between"><strong>${E(selectedCall.toolName||selectedCall.toolId)}</strong>${status(selectedCall.status)}</div><dl class="run-meta"><dt>Tool call ID</dt><dd>${E(selectedCall.id)}</dd><dt>MCP request ID</dt><dd>${E(selectedCall.requestId||'—')}</dd><dt>连接 / 版本</dt><dd>${E(selectedCall.connectionId)} · ${E(selectedCall.version||'—')}</dd></dl><h4>调用实参</h4>${json(selectedCall.args)}<h4>${selectedCall.error?'调用错误':'调用结果'}</h4>${json(selectedCall.error||selectedCall.result)}<details class="run-protocol"><summary>协议请求与响应 · ${(selectedCall.transcript||[]).length} 条</summary>${json(selectedCall.transcript||[])}</details><p class="field-help">远端内部链路未提供；此处只显示本地适配器实际记录的边界。</p><a class="btn btn-secondary btn-sm" href="#${R.getTool(selectedCall.toolId)?.kind==='plugin'?'plugin-detail':'mcp-detail'}?id=${encodeURIComponent(R.getTool(selectedCall.toolId)?.kind==='plugin'?(R.plugins.find(p=>p.toolIds?.includes(selectedCall.toolId))?.id||selectedCall.connectionId):selectedCall.connectionId)}&tab=debug&tool=${encodeURIComponent(selectedCall.toolId)}">在工具调试台打开</a></div>`:selected?`<div class="run-inspector-body"><div class="between"><strong>${E(selected.title)}</strong>${status(selected.status)}</div><dl class="run-meta"><dt>Node ID</dt><dd>${E(selected.nodeId)}</dd><dt>Execution ID</dt><dd>${E(selected.id)}</dd><dt>开始 / 结束</dt><dd>${date(selected.startedAt)} / ${date(selected.endedAt)}</dd></dl><h4>已解析输入</h4>${json(selected.inputs)}<h4>${selected.error?'节点错误':'节点输出'}</h4>${json(selected.error||selected.output)}${selected.attempts?.length?`<details><summary>${selected.attempts.length} 次尝试</summary>${json(selected.attempts)}</details>`:''}${S.btn('用这些输入单节点调试','run-test-node',{variant:'secondary',small:true,icon:'play',attrs:`data-id="${E(run.id)}" data-execution="${E(selected.id)}"`})}<p class="field-help">会创建独立调试运行，不改变这条历史记录。</p></div>`:S.empty('选择调用查看参数','执行中的节点也可以查看已有事件。')}</section></div>`;
  }
  function spanCall(call,run,total) {
    const start=Math.max(0,Math.min(98,((call.startedAt||run.created)-run.created)/total*100)), width=Math.max(1,Math.min(100-start,((call.endedAt||Date.now())-(call.startedAt||run.created))/total*100));
    return `<button type="button" class="run-span is-tool ${S.params.call===call.id?'is-selected':''}" data-action="run-select-call" data-id="${E(call.id)}"><span class="run-span-name">${S.icon('plug',14)}<strong>${E(call.toolName||call.toolId)}</strong></span>${status(call.status)}<span class="run-span-track"><i class="is-${E(call.status)}" style="left:${start}%;width:${width}%"></i></span><span class="mono small">${duration(durationOf(call))}</span></button>`;
  }
  function events(run) {
    const rows = (run.events || []).slice(0,ui.eventCount);
    return `<section class="panel"><div class="run-panel-head"><div><h3>执行事件</h3><p class="small muted">按实际记录顺序展示；时间、状态与调用 ID 来自共享执行器。</p></div>${S.btn('导出记录','run-export',{variant:'secondary',icon:'download',small:true,attrs:`data-id="${E(run.id)}"`})}</div><div class="run-events">${rows.map(ev=>`<details class="run-event"><summary><span class="mono muted">${String(ev.seq).padStart(3,'0')}</span><time class="mono small">${date(ev.time)}</time><strong class="mono">${E(ev.type)}</strong><span class="small muted">${E(ev.nodeId||ev.toolCallId||'Run')}</span></summary>${json(ev.data||{},'事件内容')}</details>`).join('')||'<p class="run-inset muted">该记录没有事件数据。</p>'}</div>${(run.events||[]).length>ui.eventCount?`<div class="run-inset">${S.btn('继续加载事件','run-more-events',{variant:'secondary'})}</div>`:''}</section>`;
  }
  function usage(run) {
    const modelEvents=(run.events||[]).filter(ev=>/model.*usage|usage.*model/.test(ev.type));
    return `<section class="panel panel-pad"><h3>本次运行用量</h3><div class="run-usage"><div><span>估算 Token</span><strong>${Number(run.tokens||0).toLocaleString('zh-CN')}</strong></div><div><span>演示费用</span><strong>¥ ${Number(run.cost||0).toFixed(4)}</strong></div><div><span>模型</span><strong class="run-usage-model">${E(run.model||'未调用模型')}</strong></div></div><p class="notice">这里的模型响应和价格为本地示例，用量标记为估算。未提供费用的外部工具不按零费用承诺。</p>${modelEvents.length?modelEvents.map(ev=>`<details class="run-event"><summary>${E(ev.data?.model||run.model||'模型')} · ${date(ev.time)}</summary>${json(ev.data)}</details>`).join(''):''}<p class="field-help">父子运行通过 parentRunId 关联。用量账本只累计各运行自身实际记录的模型调用。</p></section>`;
  }
  S.page('task',{title:'运行详情',section:'运行与改进',render(){
    const run=current();if(!run)return S.empty('还没有运行','先运行一个工作流或调试工具。',S.btn('返回任务中心','all-tasks'));
    const tab=['overview','trace','io','events','usage'].includes(S.params.tab)?S.params.tab:'overview', o=outcome(run);
    return `<div class="run-page"><div class="run-breadcrumb"><a href="#tasks">运行记录</a>${S.icon('chevron',12)}<span class="mono">${E(run.id)}</span>${run.parentRunId?`<a href="#task?id=${encodeURIComponent(run.parentRunId)}" class="text-link">查看父运行</a>`:''}</div><div class="page-heading"><div><p class="eyebrow">${E(kinds[run.kind]||'RUN DETAIL')} / ${E(run.version||'历史示例')}</p><h1>${E(run.title)}</h1><p class="page-description">${E(run.source||run.agent||'工作空间')} · ${date(run.created)}</p></div><div class="heading-actions">${status(run.status)}${actions(run)}${['done','failed','rejected','stopped'].includes(run.status)&&S.Quality?S.btn('加入评测集','run-add-dataset',{variant:'secondary',icon:'plus',attrs:`data-id="${E(run.id)}"`}):''}${S.btn('导出记录','run-export',{variant:'ghost',icon:'download',attrs:`data-id="${E(run.id)}"`})}</div></div><div class="run-facts"><span>${S.icon('clock',14)} 总耗时 <strong class="mono">${run.finishedAt?duration(run.duration??(run.finishedAt-run.created)):run.status==='waiting'?'等待处理':run.status==='running'?'进行中':'—'}</strong></span><span>${S.icon('workflow',14)} ${(run.nodeExecutions||[]).filter(x=>x.status==='done').length} 次节点完成</span><span>${S.icon('plug',14)} ${(run.toolCalls||[]).length} 次工具调用</span><span>${S.icon('folder',14)} ${E(resultLabel(run))}</span></div>${S.Planning?.card(run)||''}${approval(run)}${!run.engine&&run.status==='waiting'?`<section class="run-approval"><h3>历史示例等待确认</h3><p>批准后继续旧版演示任务；新增运行使用共享执行器。</p><div class="run-approval-actions">${S.btn('拒绝','run-legacy-approve',{variant:'secondary',attrs:`data-id="${E(run.id)}" data-approved="false"`})}${S.btn('批准','run-legacy-approve',{attrs:`data-id="${E(run.id)}" data-approved="true"`})}</div></section>`:''}${S.tabs([{id:'overview',label:'运行结果'},{id:'trace',label:'调用链',count:(run.toolCalls||[]).length},{id:'io',label:'输入与快照'},{id:'events',label:'事件记录',count:(run.events||[]).length},{id:'usage',label:'用量'}],tab,'run-tab')}<div class="run-tab-content">${tab==='overview'?`${results(run)}${run.status!=='done'&&!['failed','rejected','stopped'].includes(run.status)?`<section class="panel panel-pad"><div class="section-heading"><h3 class="section-title">当前执行</h3><a href="#task?id=${encodeURIComponent(run.id)}&tab=trace" class="text-link">查看完整调用链 ${S.icon('arrow',12)}</a></div>${(run.toolCalls||[]).slice(-3).map(c=>toolCard(run,c,true)).join('')||`<p class="muted">${run.status==='waiting'?'等待你处理上方确认。':'节点正在按配置执行，完成后按实际结果展示。'}</p>`}</section>`:''}${['stopped','rejected'].includes(run.status)?`<section class="panel panel-pad"><h3>${run.status==='stopped'?'运行已停止':'本次操作已拒绝'}</h3><p class="muted">已有执行记录和回执保留。停止或拒绝不会撤销先前已完成的操作。</p></section>`:''}`:tab==='trace'?trace(run):tab==='io'?`<div class="grid-2"><section class="panel panel-pad"><h3>运行输入</h3>${json(run.inputs||{goal:run.goal,references:run.references})}</section><section class="panel panel-pad"><h3>冻结的配置快照</h3><p class="field-help">历史运行使用启动时的配置。后续编辑不会改写这份记录。</p>${json(run.snapshot||run.workflowSnapshot||run.agentSnapshot||{version:run.version})}</section></div>`:tab==='events'?events(run):usage(run)}</div></div>`;
  },mount(){
    const id=current()?.id;let queued=false;
    return R.subscribe((run)=>{if(run.id!==id||queued||document.getElementById('app-dialog')?.open)return;const active=document.activeElement;if(active?.closest?.('[data-form="run-approval"]'))return;queued=true;queueMicrotask(()=>{queued=false;if(S.route==='task'&&current()?.id===id)S.render();});});
  }});
  S.action('run-tab',el=>S.go('task',{id:current().id,tab:el.dataset.id}));
  S.action('run-select-execution',el=>S.go('task',{id:current().id,tab:'trace',execution:el.dataset.id}));
  S.action('run-select-call',el=>S.go('task',{id:current().id,tab:'trace',call:el.dataset.id}));
  S.action('run-more-events',()=>{ui.eventCount+=60;S.render();});
  S.action('run-resume',el=>{R.resume(el.dataset.id);S.render();});
  S.action('run-approve',el=>{
    const run=R.findRun(el.dataset.id), p=run?.pending;if(!p||p.id!==el.dataset.pending||run.status!=='waiting'){S.toast('这项确认已处理或已失效','info');return;}
    const form=document.getElementById('run-approval-'+run.id+'-'+(el.dataset.context||'task')), approved=el.dataset.approved==='true', values={};
    if(approved&&form){const fields=Array.isArray(p.fields)?p.fields:[],rules={};fields.forEach((f,i)=>{const name=f.name||f.key||'field'+i,field=form.elements.namedItem(name);rules[name]=value=>{if(f.required&&f.type!=='boolean'&&!value)return '请填写'+(f.label||name);if(!value&&!f.required)return null;if(f.type==='integer'&&!Number.isInteger(Number(value)))return '请输入整数';if(f.type==='number'&&!Number.isFinite(Number(value)))return '请输入有效数字';if(['object','array'].includes(f.type)){try{const parsed=JSON.parse(value);if(f.type==='array'?!Array.isArray(parsed):parsed===null||typeof parsed!=='object'||Array.isArray(parsed))return '请输入 '+f.type+' 类型的 JSON';}catch(_){return '请输入有效 JSON';}}return null;};if(field){if(f.type==='boolean')values[name]=field.checked;else if(field.value.trim()||f.required){if(['number','integer'].includes(f.type))values[name]=Number(field.value);else if(['object','array'].includes(f.type)){try{values[name]=JSON.parse(field.value);}catch(_){}}else values[name]=field.value;}}});if(!S.validate(form,rules))return;}
    values.waitId=p.id;
    if(R.resolveApproval(run.id,approved,values)){S.toast(approved?'已确认，从等待处继续执行':'已拒绝本次操作',approved?'success':'info');S.render();}else if(form){form.querySelector('[data-approval-error]').textContent=(run.pending?.validationErrors||['提交未通过校验，请检查字段和当前等待状态']).join('；');}
  });
  S.form('run-approval',form=>S.actions['run-approve']({dataset:{id:form.dataset.id,pending:form.dataset.pending,approved:'true',context:'task'}}));
  S.action('run-legacy-approve',el=>S.resolveRun(el.dataset.id,el.dataset.approved==='true'));
  S.action('run-stop',el=>{const run=R.findRun(el.dataset.id);if(!run)return;S.modal({title:'停止“'+run.title+'”？',subtitle:'将停止后续步骤，已完成的操作和记录仍保留。',body:'<p class="small muted">停止不会撤销已经完成的目标位置写入。</p>',footer:S.btn('继续运行','modal-close',{variant:'secondary'})+S.btn('停止运行','run-confirm-stop',{variant:'danger',attrs:`data-id="${E(run.id)}"`})});});
  S.action('run-confirm-stop',el=>{const run=R.findRun(el.dataset.id);if(run?.engine)R.stop(run.id);else if(run){clearTimeout(S.timers.get(run.id));run.status='stopped';S.save();}S.closeModal();S.render();S.toast('已停止后续执行','info');});
  S.action('run-copy-result',el=>S.copy(JSON.stringify(outcome(R.findRun(el.dataset.id)).returnValue,null,2)));
  S.action('run-receipt',el=>{const run=R.findRun(el.dataset.id), receipt=outcome(run).receipts[+el.dataset.index];if(!receipt)return;S.modal({title:receipt.title||'操作回执',subtitle:'本地适配器的模拟写入记录',body:json(receipt,'操作回执'),footer:S.btn('复制目标位置','run-copy-destination',{variant:'secondary',icon:'copy',attrs:`data-id="${E(run.id)}" data-index="${+el.dataset.index}"`})+S.btn('查看工具调用','run-receipt-trace',{attrs:`data-id="${E(run.id)}" data-call="${E(receipt.toolCallId||'')}"`,icon:'arrow'})});});
  S.action('run-copy-destination',el=>S.copy(outcome(R.findRun(el.dataset.id)).receipts[+el.dataset.index].destination||''));
  S.action('run-receipt-trace',el=>{S.closeModal();const owner=S.state.runs.find(run=>(run.toolCalls||[]).some(call=>call.id===el.dataset.call));S.go('task',{id:owner?.id||el.dataset.id,tab:'trace',call:el.dataset.call});});
  function fileFor(el){const run=R.findRun(el.dataset.id);return (outcome(run).artifacts||run.artifacts||[])[+el.dataset.index];}
  S.action('run-file-preview',el=>{const a=fileFor(el);if(!a)return;S.modal({title:a.name||a.filename,subtitle:'显式生成的本地文件',body:`<pre class="run-json">${E(typeof a.content==='string'?a.content:JSON.stringify(a.content,null,2))}</pre>`,wide:true,footer:S.btn('下载文件','run-file-download',{icon:'download',attrs:`data-id="${E(el.dataset.id)}" data-index="${+el.dataset.index}"`})});});
  S.action('run-file-download',el=>{const a=fileFor(el);if(a)S.download(a.name||a.filename,typeof a.content==='string'?a.content:JSON.stringify(a.content,null,2),a.mime||'text/plain');});
  S.action('run-export',el=>{const run=R.findRun(el.dataset.id);if(run)S.download(run.id+'.json',JSON.stringify(run,null,2),'application/json');});
  S.action('run-test-node',el=>{const run=R.findRun(el.dataset.id), ex=run.nodeExecutions.find(x=>x.id===el.dataset.execution), node=(run.workflowSnapshot||run.snapshot)?.nodes?.find(n=>n.id===ex.nodeId);if(!node){S.toast('此记录没有可重用的节点快照','info');return;}const context={input:run.inputs||{},nodes:{}};run.nodeExecutions.filter(n=>n.status==='done').forEach(n=>{context.nodes[n.nodeId]=n.output;});const bindings=Object.fromEntries(Object.entries(ex.inputs||{}).map(([k,v])=>[k,{mode:'constant',value:v}]));const next=R.testNode({...node,bindings},{inputs:ex.inputs,context});S.go('task',{id:next.id});});
  S.action('run-rerun',el=>{
    const run=R.findRun(el.dataset.id);if(!run)return;
    S.modal({title:'重新运行',subtitle:'新建运行记录，并重新执行选定范围；历史记录保留。',body:`<div class="notice">需要写入目标位置的步骤会再次请求确认。</div><div class="field" style="margin-top:18px"><label class="field-label" for="run-version-choice">使用配置</label><select class="select" id="run-version-choice"><option value="snapshot">本次运行的配置快照</option value="latest">最新发布版本</option></select></div>${json(run.inputs||{},'原运行输入')}`,footer:S.btn('取消','modal-close',{variant:'secondary'})+S.btn('新建运行','run-confirm-rerun',{icon:'play',attrs:`data-id="${E(run.id)}"`})});
  });
  S.action('run-add-dataset',el=>S.Quality?.openAddFromRun(el.dataset.id));
  S.action('run-confirm-rerun',el=>{
    const old=R.findRun(el.dataset.id), latest=document.getElementById('run-version-choice')?.value==='latest';let next;
    if(['workflow','workflow-debug','subworkflow'].includes(old.kind)){const graph=old.workflowSnapshot||old.snapshot;const chosen=latest?R.publishedFlow(graph?.id):graph;if(!chosen){S.toast('没有可用的已发布配置','warning');return;}next=R.runWorkflow(chosen,{inputs:old.inputs,scenario:'success',preserveResolvedSnapshots:!latest});}
    else if(old.kind==='tool-debug'){const call=old.toolCalls[0];if(!call){S.toast('没有可重跑的工具参数','info');return;}next=R.testTool(call.toolId,call.args);}
    else if(old.kind==='agent'&&S.AgentStudio){next=S.AgentStudio.start({ephemeralAgent:old.ephemeralAgent?old.agentSnapshot||old.snapshot:undefined,agentId:old.agentSnapshot?.id||old.snapshot?.id,goal:old.inputs?.message||old.goal||old.title,mode:old.inputs?.mode||'execute',snapshot:latest?undefined:old.agentSnapshot||old.snapshot,sessionSnapshot:latest?undefined:old.sessionSnapshot,preserveResolvedSnapshots:!latest});}
    else if(old.kind==='node-debug'){const node=(old.snapshot?.nodes||old.workflowSnapshot?.nodes||[])[0]||old.snapshot?.node;if(!node){S.toast('该调试没有保存节点快照','info');return;}const execution=old.nodeExecutions.find(ex=>ex.nodeId===node.id);next=R.testNode(node,{inputs:execution?.inputs||{},context:{input:old.inputs||{},nodes:{}}});}
    if(!next)return;next.forkedFrom=old.id;S.save();S.closeModal();S.go('task',{id:next.id});
  });
  S.action('run-compare',()=>{const list=S.state.runs.slice(0,40);S.modal({title:'比较两次运行',subtitle:'对照路径、返回值、回执和配置版本。',wide:true,body:`<div class="grid-2">${['a','b'].map((key,i)=>`<div class="field"><label for="run-compare-${key}" class="field-label">${i?'对照运行':'基准运行'}</label><select class="select" id="run-compare-${key}">${list.map((r,j)=>`<option value="${E(r.id)}" ${j===i?'selected':''}>${E(r.title)} · ${E(r.id.slice(-7))}</option>`).join('')}</select></div>`).join('')}</div><div id="run-comparison"></div>`,footer:S.btn('比较','run-compare-show',{icon:'layers'})});S.actions['run-compare-show']();});
  S.action('run-compare-show',()=>{const a=R.findRun(document.getElementById('run-compare-a').value),b=R.findRun(document.getElementById('run-compare-b').value);document.getElementById('run-comparison').innerHTML=`<div class="grid-2">${[a,b].map(r=>`<section><h3>${E(r.title)}</h3><p class="small">${status(r.status)} ${E(r.version||'—')}</p><dl class="run-meta"><dt>节点路径</dt><dd>${E((r.nodeExecutions||[]).filter(n=>n.status==='done').map(n=>n.title).join(' → ')||'未记录')}</dd><dt>结果</dt><dd>${E(resultLabel(r))}</dd><dt>估算 Token</dt><dd>${Number(r.tokens||0)}</dd></dl>${json(outcome(r))}</section>`).join('')}</div>`;});
})();
